function LengthOfLIS(nums: int[]) -> int {
  let n = nums.length();
  if (n == 0) {
    return 0;
  }
  let dp: int[] = [];
  let i = 0;
  while (i < n) {
    dp.push(1);
    i += 1;
  }
  let best = 1;
  let a = 1;
  while (a < n) {
    let b = 0;
    while (b < a) {
      if (nums[b] < nums[a]) {
        if (dp[b] + 1 > dp[a]) {
          dp[a] = dp[b] + 1;
        }
      }
      b += 1;
    }
    if (dp[a] > best) {
      best = dp[a];
    }
    a += 1;
  }
  return best;
}
